harness.enable:
const COMPLEX_TEXT_MIN_CHARS = 200;
const COMPLEX_SENTENCE_MIN_WORDS = 15;
const complexElements = Array.from(document.querySelectorAll('main p, [role="main"] p, article p, #content p, .content p, p'))
  .filter(el => {
    if (el.dataset.ai4a11yProcessed || el.dataset.ai4a11ySimplified) return false;
    if (el.querySelector('p, div, article, section, table')) return false;
    if ((el.textContent?.length || 0) <= COMPLEX_TEXT_MIN_CHARS) return false;
    const text = m.proseText(el);
    return text.length > COMPLEX_TEXT_MIN_CHARS &&
      text.split(/[.!?]/).some(s => s.trim().split(/\s+/).length > COMPLEX_SENTENCE_MIN_WORDS);
  }).slice(0, 3);
for (const el of complexElements) {
  await m.simplifyText(el);
}

const longElements = Array.from(document.querySelectorAll('main article, [role="main"] article, article, main section, section'))
  .filter(el => {
    if (el.dataset.ai4a11ySummarize) return false;
    if (el.closest('[data-ai4a11y-summarize]')) return false;
    if (el.querySelector('article, section')) return false;
    const text = m.proseText(el);
    return text.length >= 500;
  }).slice(0, 1);
for (const el of longElements) {
  await m.summarizeContent(el);
}
